const body = $input.first().json.body || $input.first().json;
const brand = (body.brand || '').toString().trim();
if (!brand) throw new Error('Missing "brand". Send JSON: { "brand": "Nike" }');

// How many of the returned sources to actually audit. Each one costs a Tavily
// extract + an LLM call, so keep it small on a free tier.
let max_sources = parseInt(body.max_sources, 10);
if (!Number.isFinite(max_sources) || max_sources < 1) max_sources = 3;
max_sources = Math.min(max_sources, 8);

return [{ json: { brand, max_sources } }];

// Turn the brand's sources into one item per link to audit.
const cfg = $('Normalize Input').first().json;
const brand = $input.first().json;
const sources = Array.isArray(brand.sources) ? brand.sources : [];

// The cause we ask the verifier about is the reason Agent 1 reported. If it found
// nothing, fall back to a generic phrasing so the verifier still has something concrete.
const cause = (brand.reason && brand.reason.trim())
  ? brand.reason.trim().slice(0, 300)
  : `consumer boycott of ${brand.brand}`;

const picked = sources.filter(s => s && s.url).slice(0, cfg.max_sources);
if (picked.length === 0) return [{ json: { __none: true } }];

return picked.map(s => ({ json: { url: s.url, title: s.title || '', product: brand.brand, cause } }));

// Combine the brand verdict with the per-source audits into one report.
const brand = $('Call /boycott-check').first().json;
const audits = $input.all().map(i => i.json).filter(j => j && !j.__none && j.url);

const sources = audits.map(a => ({
  url: a.url,
  verdict: a.verdict || 'unreachable',
  support_strength: Number(a.support_strength) || 0,
  credibility: Number(a.credibility) || 0,
}));

// Evidence score = deterministic, same principle as everywhere else in this project.
// A source is only worth as much as (how well it backs the claim) x (how trustworthy it is).
const quality = sources
  .map(s => (s.support_strength * s.credibility) / 100)
  .sort((a, b) => b - a)
  .slice(0, 3);
const evidence_score = quality.length
  ? Math.round(quality.reduce((a, b) => a + b, 0) / quality.length)
  : 0;

const sources_verified = sources.filter(s => s.verdict === 'verified').length;

return [{ json: {
  brand: brand.brand,
  status: brand.status,
  confidence: brand.confidence,      // does a boycott appear to exist?
  reason: brand.reason || '',
  evidence_score,                    // do the sources actually hold up? 0-100
  sources_checked: sources.length,
  sources_verified,
  sources,
  checked_at: new Date().toISOString(),
} }];
